import grpc
import json
import boto3
from concurrent import futures
import logging
from proto import workflow_pb2, workflow_pb2_grpc

logger = logging.getLogger(__name__)

class WorkflowService(workflow_pb2_grpc.WorkflowServiceServicer):
    """gRPC service that triggers Step Functions workflows and reads DynamoDB results."""

    def __init__(self):
        self.sfn_client = boto3.client('stepfunctions')
        self.dynamodb = boto3.resource('dynamodb')
        self.table = self.dynamodb.Table('workflow-results')
        self.state_machine_arn = 'arn:aws:states:us-east-1:123456789012:stateMachine:ProcessWorkflow'

    def StartWorkflow(self, request, context):
        """Starts a Step Functions workflow with metadata from gRPC context."""
        metadata = dict(context.invocation_metadata())

        # Extract tenant context from gRPC metadata
        tenant_id = metadata.get('x-tenant-id', '')
        user_id = metadata.get('x-user-id', '')
        correlation_id = metadata.get('x-correlation-id', '')

        # Build Step Functions input from request + metadata
        # NOTE: metadata values are passed directly into the workflow input
        workflow_input = {
            'tenant_id': tenant_id,
            'user_id': user_id,
            'correlation_id': correlation_id,
            'action': request.action,
            'payload': request.payload,
            'target_partition': f"{tenant_id}#{user_id}"
        }

        try:
            response = self.sfn_client.start_execution(
                stateMachineArn=self.state_machine_arn,
                input=json.dumps(workflow_input)
            )
            return workflow_pb2.WorkflowResponse(
                execution_arn=response['executionArn'],
                status='RUNNING'
            )
        except Exception as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details(str(e))
            return workflow_pb2.WorkflowResponse()

    def GetWorkflowResult(self, request, context):
        """Retrieves workflow results from DynamoDB using tenant context."""
        metadata = dict(context.invocation_metadata())

        # Attacker can inject arbitrary tenant_id via gRPC metadata
        tenant_id = metadata.get('x-tenant-id', '')
        user_id = metadata.get('x-user-id', '')
        result_id = request.result_id

        # Construct partition key from metadata - no server-side validation
        partition_key = f"{tenant_id}#{user_id}"

        try:
            response = self.table.get_item(
                Key={
                    'pk': partition_key,
                    'sk': f"RESULT#{result_id}"
                }
            )
            item = response.get('Item', {})
            return workflow_pb2.ResultResponse(
                data=json.dumps(item),
                status='COMPLETED'
            )
        except self.dynamodb.meta.client.exceptions.ClientError as e:
            if e.response['Error']['Code'] == 'AccessDeniedException':
                context.set_code(grpc.StatusCode.PERMISSION_DENIED)
                context.set_details('Access denied to requested resource')
            else:
                context.set_code(grpc.StatusCode.INTERNAL)
                context.set_details(str(e))
            return workflow_pb2.ResultResponse()

    def BatchGetResults(self, request, context):
        """Batch retrieval - also vulnerable to metadata injection."""
        metadata = dict(context.invocation_metadata())
        tenant_id = metadata.get('x-tenant-id', '')

        # No validation that caller actually belongs to this tenant
        response = self.table.query(
            KeyConditionExpression='pk = :pk',
            ExpressionAttributeValues={
                ':pk': f"{tenant_id}#batch"
            }
        )
        results = [json.dumps(item) for item in response.get('Items', [])]
        return workflow_pb2.BatchResultResponse(results=results)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    workflow_pb2_grpc.add_WorkflowServiceServicer_to_server(
        WorkflowService(), server
    )
    server.add_insecure_port('[::]:50051')
    server.start()
    logger.info('gRPC server started on port 50051')
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
